import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

type UsageMeterState = "unknown" | "normal" | "warning" | "over-limit";

type UsageMeterProps = Omit<
    ComponentProps<"section">,
    "aria-label" | "children"
> & {
    label: string;
    used: number | null;
    limit: number | null;
    unit?: string;
    estimated?: boolean;
    estimatedLabel?: string;
    warningThreshold?: number;
    details?: ReactNode;
    action?: ReactNode;
};

function UsageMeter({
    label,
    used,
    limit,
    unit = "단위",
    estimated = false,
    estimatedLabel = "추정치",
    warningThreshold = 0.8,
    details,
    action,
    className,
    ...props
}: UsageMeterProps) {
    if (typeof label !== "string" || !label.trim()) {
        throw new Error("UsageMeter requires a label.");
    }
    if (used !== null &&
        (typeof used !== "number" || !Number.isFinite(used) || used < 0)) {
        throw new RangeError("UsageMeter used must be null or a finite non-negative number.");
    }
    if (limit !== null &&
        (typeof limit !== "number" || !Number.isFinite(limit) || limit <= 0)) {
        throw new RangeError("UsageMeter limit must be null or a finite positive number.");
    }
    if (typeof unit !== "string" || typeof estimated !== "boolean" ||
        typeof estimatedLabel !== "string" || !estimatedLabel.trim()) {
        throw new TypeError("UsageMeter labels and estimated state are invalid.");
    }
    if (typeof warningThreshold !== "number" ||
        !Number.isFinite(warningThreshold) || warningThreshold < 0 ||
        warningThreshold > 1) {
        throw new RangeError(
            "UsageMeter warningThreshold must be a ratio from 0 to 1.",
        );
    }

    const known = used !== null && limit !== null;
    const ratio = known ? used / limit : null;
    const state: UsageMeterState = !known
        ? "unknown"
        : used > limit
            ? "over-limit"
            : ratio !== null && ratio >= warningThreshold
                ? "warning"
                : "normal";
    const suffix = unit.trim();
    const amount = (value: number) =>
        `${String(value)}${suffix ? ` ${suffix}` : ""}`;

    let usageText: string;
    if (used !== null && limit !== null) {
        usageText = `${amount(used)} / ${amount(limit)}`;
    } else if (used !== null) {
        usageText = `${amount(used)} 사용 · 한도 확인 불가`;
    } else if (limit !== null) {
        usageText = `사용량 확인 불가 · 한도 ${amount(limit)}`;
    } else {
        usageText = "사용량 확인 불가";
    }

    const statusText = state === "over-limit"
        ? "한도 초과"
        : state === "warning"
            ? "한도 임박"
            : state === "normal"
                ? "한도 이내"
                : "사용량 확인 불가";

    return (
        <section aria-label={label} data-ui="usage-meter"
            data-state={state}
            className={cn("min-w-0 text-foreground", className)} {...props}>
            <div className="flex min-w-0 flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
                <strong className="min-w-0 text-sm font-semibold">{label}</strong>
                <span role="status" className={cn(
                    "text-xs",
                    state === "over-limit" && "text-danger",
                    state === "warning" && "text-warning",
                    state === "unknown" && "text-muted",
                )}>
                    {statusText}
                </span>
            </div>
            <p className="m-0 mt-1 text-sm text-muted">
                {usageText}
                {estimated && (
                    <span className="ml-1">· {estimatedLabel.trim()}</span>
                )}
            </p>
            {known && (
                <progress value={Math.min(used, limit)} max={limit}
                    aria-label={`${label} 사용량`}
                    aria-valuetext={`${usageText}${estimated
                        ? ` · ${estimatedLabel.trim()}`
                        : ""}`}
                    className={cn(
                        "mt-[var(--space-2)] h-2 w-full rounded-full " +
                        "bg-surface-subtle",
                        state === "over-limit"
                            ? "[&::-webkit-progress-value]:bg-danger " +
                                "[&::-moz-progress-bar]:bg-danger"
                            : state === "warning"
                                ? "[&::-webkit-progress-value]:bg-warning " +
                                    "[&::-moz-progress-bar]:bg-warning"
                                : "[&::-webkit-progress-value]:bg-accent " +
                                    "[&::-moz-progress-bar]:bg-accent",
                    )} />
            )}
            {details != null && (
                <details className="mt-[var(--space-2)] text-sm">
                    <summary className="cursor-pointer rounded-sm text-xs text-muted focus-visible:outline-2 focus-visible:outline-focus">
                        자세히 보기
                    </summary>
                    <div className="mt-1 min-w-0 break-words">
                        {details}
                    </div>
                </details>
            )}
            {action != null && (
                <div className="mt-[var(--space-2)]">{action}</div>
            )}
        </section>
    );
}

export { UsageMeter };
export type { UsageMeterProps, UsageMeterState };
